param([Parameter(Mandatory=$true)][string]$ServerUrl)\n$ServerUrl=$ServerUrl.TrimEnd('/')\n$ext=Join-Path $PSScriptRoot 'extension'\nSet-Content -Path (Join-Path $ext 'config.js') -Value "const BIDPILOT_LICENSE_SERVER = \"$ServerUrl\";" -Encoding utf8\n$downloads=Join-Path $PSScriptRoot 'downloads'\nforeach($platform in @('Windows','macOS')){ $zip=Join-Path $downloads ("BidPilot-$platform.zip"); if(Test-Path $zip){Remove-Item $zip -Force}; Compress-Archive -Path (Join-Path $ext '*') -DestinationPath $zip -Force }\nWrite-Host "Customer ZIPs rebuilt for $ServerUrl"\n